// Captação – etapa 3: peças comuns (avaliação, avisos, decisão e acompanhamento).
// O gerador embute este arquivo antes do código de cada fluxo; os testes carregam os dois juntos (carregar.js).
// Sem dependências do n8n (nada de luxon): datas são texto AAAA-MM-DD no fuso de São Paulo.

var BASE_DECISAO = 'https://n8n.modal.org.br/webhook/captacao-decisao';
var BASE_REGISTRO = 'https://n8n.modal.org.br/webhook/captacao-decisao-registrar';
var TG_ENVIO = 'https://discricionarias.transferegov.sistema.gov.br/';
var TG_ROTULO = 'Enviar proposta no Transferegov (exige login gov.br)';
var RODAPE = 'Mensagem automática da captação de oportunidades do Instituto Modal.';
var ROTULO_PARCEIRA = 'Em parceria com uma empresa (cliente ou parceiro do Modal)';

var REC = { seguir: 'Seguir', avaliar: 'Avaliar', nao_seguir: 'Não seguir' };
var ESF = { baixo: 'Baixo', medio: 'Médio', alto: 'Alto' };
var SIT = { nova: 'Sem resposta', avisada: 'Sem resposta', concorrer: 'Vamos concorrer', talvez: 'Talvez', nao_serve: 'Não serve', enviada: 'Proposta enviada', ganhou: 'Ganhou', perdeu: 'Perdeu', desistiu: 'Desistiu' };
var DECIDIVEL = ['nova', 'avisada', 'talvez', 'concorrer'];
var CERTS = {
  federal: { nome: 'Certidão de débitos federais (Receita Federal e PGFN)', url: 'https://servicos.receitafederal.gov.br/servico/certidoes/', nota: 'informe o CNPJ; sai na hora quando não há pendência.' },
  fgts: { nome: 'Certificado de Regularidade do FGTS (CRF, Caixa)', url: 'https://consulta-crf.caixa.gov.br/consultacrf/pages/consultaEmpregador.jsf', nota: 'vale 30 dias e só pode ser renovado a partir de 5 dias antes de vencer: por isso é emitido perto da entrega.' },
  trabalhista: { nome: 'Certidão Negativa de Débitos Trabalhistas (CNDT, TST)', url: 'https://cndt-certidao.tst.jus.br/inicio.faces', nota: 'informe o CNPJ.' },
  df: { nome: 'Certidão negativa de débitos do Distrito Federal (Receita do DF, Secretaria de Economia)', url: 'https://ww1.receita.fazenda.df.gov.br/cidadao/certidoes/Certidao', nota: 'confira a validade impressa na certidão.' }
};
var ORDEM_CERT = ['federal', 'fgts', 'trabalhista', 'df'];

function txt(v) { return String(v == null ? '' : v).trim(); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
// Só endereço público (mesma trava da triagem): o link do edital vem do texto lido pela IA e não pode levar o robô a serviço interno.
function enderecoPublico(u) {
  var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)(:(?:80|443))?([\/?#]|$)/i);
  if (!m) return false;
  var h = m[1].toLowerCase().replace(/\.$/, '');
  // Nome de domínio comum: rótulos só com letras, números e hífen, terminando em domínio de letras
  // (recusa IP em qualquer grafia, como 0x7f.0.0.1 ou 0177.1, barra invertida e %).
  if (!/^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/.test(h)) return false;
  if (/(^|\.)(localhost|local|internal|lan|home|arpa)$/.test(h)) return false;
  if (/(^|\.)modal\.org\.br$/.test(h)) return false;
  return true;
}
function seguro(u) { var v = txt(u); return /^https?:\/\/[^\s"'<>]+$/i.test(v) && enderecoPublico(v) ? v : ''; }
function normTxt(s) { return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function tam(s) { return String(s || '').replace(/\s+/g, '').length; }
function itensDe(v) { return (Array.isArray(v) ? v : String(v || '').split('\n')).map(function (s) { return String(s).replace(/^[-•*\s]+/, '').trim(); }).filter(Boolean); }

// ---------- datas (AAAA-MM-DD, fuso de São Paulo, sem horário de verão desde 2019) ----------
function dia(v) {
  if (v == null || v === '') return '';
  if (Object.prototype.toString.call(v) === '[object Date]') v = v.toISOString();
  var s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  var t = Date.parse(s);
  if (isNaN(t)) { var m = s.match(/^(\d{4}-\d{2}-\d{2})/); return m ? m[1] : ''; }
  return new Date(t - 3 * 3600 * 1000).toISOString().slice(0, 10);
}
function utc(iso) { return Date.parse(iso + 'T00:00:00Z'); }
function diasEntre(a, b) { return Math.round((utc(b) - utc(a)) / 86400000); }
function somaDias(iso, n) { return new Date(utc(iso) + n * 86400000).toISOString().slice(0, 10); }
function br(iso) { var m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[3] + '/' + m[2] + '/' + m[1] : ''; }
function faltam(n) { return n <= 0 ? 'é hoje' : n === 1 ? 'falta 1 dia' : 'faltam ' + n + ' dias'; }
function porPrazo(a, b) { return (a.prazo || '9999-12-31').localeCompare(b.prazo || '9999-12-31'); }

// ---------- execução: produção x teste ----------
// Produção = fluxo gerado com --producao (modoTeste false) E execução agendada. Manual ou modoTeste: e-mail só para o endereço de teste,
// com [TESTE] no assunto, e só oportunidades "[TESTE]" têm a situação alterada. Em produção, "[TESTE]" é ignorado.
function contexto(cfg, modoN8n) {
  var agendada = modoN8n === 'production' || modoN8n === 'trigger';
  var producao = cfg.modoTeste === false && agendada;
  return { producao: producao, para: producao ? cfg.lista : cfg.emailTeste, prefixo: producao ? '' : '[TESTE] ' };
}
function ehTeste(op) { return /^\s*\[TESTE\]/i.test(txt(op.titulo)) || /^\s*\[TESTE\]/i.test(txt(op.titulo_oficial)); }

// ---------- oportunidade ----------
function ehApiTransferegov(u) { return /^https?:\/\/api-publica\.transferegov\./i.test(txt(u)); }
// Link para leitura de gente. Programa do Transferegov não tem página pública (a API devolve JSON): vai o caminho de envio e a instrução de busca.
function linkOp(op) {
  var cands = [seguro(op.link_edital_oficial), seguro(op.url)].filter(Boolean);
  var normal = cands.filter(function (u) { return !ehApiTransferegov(u); })[0] || '';
  var prog = txt(op.tipo_oportunidade) === 'programa_aberto';
  if (normal) return { tg: false, url: normal, rotulo: prog ? 'Programa' : 'Edital oficial' };
  if (cands.some(ehApiTransferegov) || prog) return { tg: true, url: TG_ENVIO, rotulo: TG_ROTULO };
  return { tg: false, url: '', rotulo: 'Edital oficial' };
}
function infoOp(op) {
  return {
    chave: txt(op.chave), titulo: txt(op.titulo_oficial) || txt(op.titulo), ofertante: txt(op.ofertante), prazo: dia(op.prazo), valor: txt(op.valor),
    resumo: txt(op.resumo), publico: txt(op.publico_elegivel), papel: txt(op.papel_modal), fonte: txt(op.fonte), prog: txt(op.tipo_oportunidade) === 'programa_aberto',
    link: linkOp(op), teste: ehTeste(op)
  };
}
function papelRotulo(papel) {
  if (papel === 'parceira') return ROTULO_PARCEIRA;
  if (papel === 'proponente') return 'O Modal pode ser o proponente (ICT)';
  return 'Papel do Modal a confirmar no edital';
}

// ---------- blocos de e-mail (formato do subfluxo "Modal – Enviar e-mail") ----------
function P(html) { return { tipo: 'paragrafo', html: html }; }
function PT(texto) { return { tipo: 'paragrafo', texto: texto }; }
function H(texto) { return { tipo: 'subtitulo', texto: texto }; }
function UL(itens) { return { tipo: 'lista', itens: itens }; }
function AV(texto, tom) { return { tipo: 'aviso', texto: texto, tom: tom || 'atencao' }; }
function CAMPOS(itens, titulo) { return { tipo: 'campos', titulo: titulo, itens: itens }; }
function BOTOES(itens) { return { tipo: 'botoes', itens: itens }; }
function blocoLink(op) {
  var i = op.link ? op : infoOp(op);
  if (i.link.tg) return P('<b>Programa no Transferegov:</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.rotulo) + '</a>. No portal, busque pelo nome do programa: <i>' + esc(i.titulo) + '</i>.');
  if (i.link.url) return P('<b>' + esc(i.prog ? 'Programa oficial' : 'Edital oficial') + ':</b> <a href="' + esc(i.link.url) + '">' + esc(i.link.url) + '</a>');
  return PT('Link do edital não identificado; procure no site do ofertante.');
}
function urlDecisao(token, d) { return BASE_DECISAO + '?t=' + encodeURIComponent(token) + '&d=' + d; }
function botoesDecisao(token) { return BOTOES([{ rotulo: 'Vamos concorrer', url: urlDecisao(token, 'concorrer') }, { rotulo: 'Talvez', url: urlDecisao(token, 'talvez') }, { rotulo: 'Não serve', url: urlDecisao(token, 'nao_serve') }]); }
function novoEmail(cfg, ctx, e) {
  return {
    para: ctx.para, assunto: ctx.prefixo + e.assunto, nomeRemetente: cfg.remetente, responderPara: cfg.lista,
    etiqueta: e.etiqueta, titulo: e.titulo, previa: e.previa, blocos: e.blocos, rodape: RODAPE, _marca: e.marca || null
  };
}

// ---------- resposta do subfluxo de e-mail ----------
// O subfluxo devolve a resposta do Gmail (tem "id") ou falha. Só conta como enviado o que voltou com id.
function enviado(resp) { return !!(resp && typeof resp === 'object' && !resp.error && typeof resp.id === 'string' && resp.id); }

// Captação – Avisos: aviso diário (8h) e resumo semanal (segunda, 8h30). Funções puras; embutido depois de comum.js.

var EXPLICA_PROGRAMA = 'Programa federal do Transferegov aberto a propostas de organizações da sociedade civil, sem edital nem seleção entre concorrentes: a organização cadastra a proposta até a data limite e o órgão decide se apoia, conforme o enquadramento e o orçamento. Não há garantia de recurso; costuma valer buscar apoio do órgão concedente para o repasse.';
var AVISO_PARCIAL = 'Avaliação parcial: o dossiê ou a carteira de projetos do Modal ainda estão incompletos (ou o edital não pôde ser lido por inteiro). Confira os pontos antes de decidir.';
var LIMITE_DIARIO = 25;
var LIMITE_SECAO = 40;

function diasAte(prazo, hoje) { return diasEntre(hoje, prazo); }
function aberta(i, hoje) { return !i.prazo || i.prazo >= hoje; }

// Junta cada avaliação com a oportunidade; em produção "[TESTE]" é ignorado. marcar: só produção ou oportunidade de teste têm a situação alterada.
function elegiveis(o) {
  var ops = {};
  (o.oportunidades || []).forEach(function (op) { if (op && op.chave && op.situacao_triagem === 'aprovada') ops[op.chave] = op; });
  var out = [];
  (o.avaliacoes || []).forEach(function (a) {
    if (!a || !a.id || !a.chave_oportunidade || !/^[a-f0-9]{48}$/.test(txt(a.token))) return;
    var op = ops[a.chave_oportunidade]; if (!op) return;
    var i = infoOp(op);
    if (o.ctx.producao && i.teste) return;
    out.push({ a: a, op: op, i: i, linhaBase: op.linha_base === true, marcar: o.ctx.producao || i.teste });
  });
  return out;
}

function cabecalho(e, hoje) {
  var a = e.a, i = e.i;
  var campos = [
    { rotulo: i.prog ? 'Data limite do programa' : 'Prazo', valor: i.prazo ? br(i.prazo) + ' (' + faltam(diasAte(i.prazo, hoje)) + ')' : 'não informado' },
    { rotulo: 'Ofertante', valor: i.ofertante || 'não informado' },
    { rotulo: 'Valor', valor: i.valor || 'não informado' },
    { rotulo: 'Papel do Modal', valor: papelRotulo(i.papel) },
    { rotulo: 'Avaliação', valor: 'Aderência ' + a.aderencia + '/100 · ' + (REC[a.recomendacao] || a.recomendacao) + ' · esforço ' + (ESF[a.esforco] || a.esforco) + (txt(a.projeto_sugerido) ? ' · projeto da carteira: ' + a.projeto_sugerido : '') }
  ];
  return [H(i.titulo + (i.prog ? ' (programa aberto, sem seleção)' : '')), CAMPOS(campos)];
}
// completo: com o que falta e os próximos passos; senão só a justificativa.
function blocosItem(e, hoje, completo, comBotoes) {
  var a = e.a, i = e.i;
  var b = cabecalho(e, hoje);
  if (i.prog) b.push(PT(EXPLICA_PROGRAMA));
  if (i.resumo) b.push(PT(i.resumo));
  if (a.avaliacao_parcial) b.push(AV(AVISO_PARCIAL));
  b.push(PT(txt(a.justificativa)));
  if (completo && txt(a.requisitos_faltantes)) { b.push(H('O que falta')); b.push(UL(itensDe(a.requisitos_faltantes))); }
  if (completo && txt(a.proximos_passos)) { b.push(H('Próximos passos')); b.push(UL(itensDe(a.proximos_passos))); }
  b.push(blocoLink(i));
  if (comBotoes) b.push(botoesDecisao(a.token));
  return b;
}
var NOTA_BOTOES = 'Responda pelos botões de cada oportunidade. Cada botão abre uma página para confirmar; abrir o link sozinho não registra nada.';

// ---------- aviso diário ----------
function avisoDiario(o) {
  var hoje = o.hoje;
  var todas = elegiveis(o);
  // linha de base nunca é novidade; vencida não avisa; "não seguir" não avisa
  var novas = todas.filter(function (e) { return e.a.situacao === 'nova' && !e.linhaBase && aberta(e.i, hoje) && e.a.recomendacao !== 'nao_seguir'; }).sort(function (x, y) { return porPrazo(x.i, y.i); });
  var atual = todas.filter(function (e) { return e.a.atualizacao_pendente === true && e.a.situacao !== 'nova' && aberta(e.i, hoje); }).sort(function (x, y) { return porPrazo(x.i, y.i); });
  if (!novas.length && !atual.length) return [];
  var mostradas = novas.slice(0, LIMITE_DIARIO);
  var blocos = [];
  if (mostradas.length) {
    blocos.push(PT('Estas oportunidades foram avaliadas desde o último aviso, da mais urgente para a menos urgente. ' + NOTA_BOTOES));
    mostradas.forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, true, true)); });
    if (novas.length > mostradas.length) blocos.push(AV('Mais ' + (novas.length - mostradas.length) + ' oportunidades avaliadas ficam para o próximo aviso.'));
  }
  if (atual.length) {
    blocos.push(H('Atualizações'));
    blocos.push(PT('Estas oportunidades já tinham sido avisadas e tiveram prazo ou valor alterados (retificação ou prorrogação). Confira os dados atuais no edital oficial.'));
    atual.forEach(function (e) {
      var i = e.i, a = e.a;
      var mud = (txt(e.op.motivo).match(/atualizada por retifica[çc][ãa]o em [^|]*/gi) || []).pop() || '';
      blocos.push(H(i.titulo));
      blocos.push(CAMPOS([
        { rotulo: i.prog ? 'Data limite atual' : 'Prazo atual', valor: i.prazo ? br(i.prazo) + ' (' + faltam(diasAte(i.prazo, hoje)) + ')' : 'não informado' },
        { rotulo: 'Valor atual', valor: i.valor || 'não informado' },
        { rotulo: 'O que mudou', valor: mud ? mud.replace(/^atualizada por /i, '').trim() : 'prazo ou valor' },
        { rotulo: 'Resposta atual', valor: SIT[a.situacao] || a.situacao }
      ]));
      blocos.push(blocoLink(e.i));
      if (DECIDIVEL.indexOf(a.situacao) >= 0) blocos.push(botoesDecisao(a.token));
    });
  }
  var n = novas.length, partes = [];
  if (n) partes.push(n + (n === 1 ? ' nova oportunidade' : ' novas oportunidades'));
  if (atual.length) partes.push(atual.length + (atual.length === 1 ? ' atualização' : ' atualizações'));
  var prox = mostradas.length ? mostradas[0].i.prazo : '';
  return [novoEmail(o.cfg, o.ctx, {
    assunto: 'Oportunidades: ' + partes.join(' e ') + (prox ? ' (próximo prazo ' + br(prox) + ')' : ''),
    etiqueta: 'Captação de oportunidades', titulo: 'Aviso diário de oportunidades', previa: partes.join(' e '), blocos: blocos,
    marca: {
      canal: 'diario',
      avisos: mostradas.filter(function (e) { return e.marcar; }).map(function (e) { return e.a.id; }),
      atualizacoes: atual.filter(function (e) { return e.marcar; }).map(function (e) { return e.a.id; })
    }
  })];
}

// ---------- resumo semanal ----------
function resumoSemanal(o) {
  var hoje = o.hoje, limite30 = somaDias(hoje, 30), inicioSemana = somaDias(hoje, -7);
  var todas = elegiveis(o);
  var abertas = todas.filter(function (e) { return aberta(e.i, hoje) && ['nova', 'avisada', 'talvez', 'concorrer'].indexOf(e.a.situacao) >= 0; }).sort(function (x, y) { return porPrazo(x.i, y.i); });
  var prox = abertas.filter(function (e) { return e.i.prazo && e.i.prazo <= limite30; });
  var semDecisao = abertas.filter(function (e) { return ['nova', 'avisada', 'talvez'].indexOf(e.a.situacao) >= 0; });
  var pouco = semDecisao.filter(function (e) { return e.a.recomendacao === 'nao_seguir'; });
  var progs = semDecisao.filter(function (e) { return e.a.recomendacao !== 'nao_seguir' && e.i.prog; });
  var editais = semDecisao.filter(function (e) { return e.a.recomendacao !== 'nao_seguir' && !e.i.prog; });
  if (!abertas.length) return [];
  var mostrados = {};
  function ate(lista) { var r = lista.slice(0, LIMITE_SECAO); r.forEach(function (e) { mostrados[e.a.id] = e; }); return r; }
  function resto(lista) { return lista.length > LIMITE_SECAO ? [AV('Mais ' + (lista.length - LIMITE_SECAO) + ' nesta seção não cabem neste e-mail; entram nas próximas segundas, conforme os prazos passam.')] : []; }
  var blocos = [PT('Resumo do que está aberto e avaliado, por prazo. Responda pelos botões de cada oportunidade ainda sem decisão. ' + NOTA_BOTOES)];
  if (prox.length) {
    blocos.push(H('Prazos dos próximos 30 dias (' + prox.length + ')'));
    var pl = ate(prox);
    blocos.push(UL(pl.map(function (e) { return br(e.i.prazo) + ' — ' + e.i.titulo + (e.i.prog ? ' (programa aberto)' : '') + ' — ' + (SIT[e.a.situacao] || e.a.situacao); })));
    blocos = blocos.concat(resto(prox));
  }
  if (editais.length) {
    blocos.push(H('Abertas, ainda sem decisão (' + editais.length + ')'));
    ate(editais).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(editais));
  }
  if (progs.length) {
    blocos.push(H('Programas abertos a propostas (sem seleção) (' + progs.length + ')'));
    blocos.push(PT(EXPLICA_PROGRAMA));
    ate(progs).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(progs));
  }
  if (pouco.length) {
    blocos.push(H('Avaliadas como pouco aderentes (' + pouco.length + ')'));
    blocos.push(PT('Ficaram com recomendação de não seguir; estão aqui para conferência.'));
    ate(pouco).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(pouco));
  }
  // decisões e resultados dos últimos 7 dias
  var feitos = todas.filter(function (e) {
    var d = dia(e.a.resultado_em) || dia(e.a.decidido_em);
    return d && d >= inicioSemana && ['concorrer', 'talvez', 'nao_serve', 'enviada', 'ganhou', 'perdeu', 'desistiu'].indexOf(e.a.situacao) >= 0;
  });
  if (feitos.length) {
    blocos.push(H('Decisões e resultados da semana (' + feitos.length + ')'));
    blocos.push(UL(feitos.map(function (e) {
      var s = SIT[e.a.situacao] + (e.a.situacao === 'nao_serve' && txt(e.a.motivo_nao_serve) ? ' (motivo: ' + e.a.motivo_nao_serve + ')' : '') + (e.a.situacao === 'desistiu' && txt(e.a.motivo_desistencia) ? ' (motivo: ' + e.a.motivo_desistencia + ')' : '');
      return e.i.titulo + (e.i.prog ? ' (programa aberto)' : '') + ' — ' + s;
    })));
  }
  // quadro por fonte, desde o início
  var q = {};
  todas.forEach(function (e) {
    var f = e.i.fonte || 'Sem fonte', r = q[f] || (q[f] = { avisadas: 0, concorrer: 0, enviadas: 0, ganhas: 0 }), a = e.a;
    if (a.avisado_em || a.situacao !== 'nova') r.avisadas++;
    if (['concorrer', 'enviada', 'ganhou', 'perdeu', 'desistiu'].indexOf(a.situacao) >= 0) r.concorrer++;
    if (['enviada', 'ganhou', 'perdeu'].indexOf(a.situacao) >= 0 || (a.situacao === 'desistiu' && a.enviada_em)) r.enviadas++;
    if (a.situacao === 'ganhou') r.ganhas++;
  });
  var fontes = Object.keys(q).filter(function (f) { return q[f].avisadas || q[f].concorrer; }).sort(function (x, y) { return (q[y].avisadas - q[x].avisadas) || x.localeCompare(y); });
  if (fontes.length) {
    blocos.push(H('Quadro por fonte (desde o início)'));
    blocos.push(CAMPOS(fontes.map(function (f) { return { rotulo: f, valor: 'avisadas ' + q[f].avisadas + ' · concorrer ' + q[f].concorrer + ' · enviadas ' + q[f].enviadas + ' · ganhas ' + q[f].ganhas }; })));
  }
  // as avaliações "nova" que entraram no e-mail viram avisada (canal semanal); linha de base inclusive
  var ids = Object.keys(mostrados).map(function (k) { return mostrados[k]; }).filter(function (e) { return e.a.situacao === 'nova' && e.marcar; }).map(function (e) { return e.a.id; });
  var n = abertas.length;
  return [novoEmail(o.cfg, o.ctx, {
    assunto: 'Resumo semanal de oportunidades: ' + n + (n === 1 ? ' aberta' : ' abertas') + (prox.length ? ', ' + prox.length + ' com prazo em 30 dias' : ''),
    etiqueta: 'Captação de oportunidades', titulo: 'Resumo semanal de oportunidades', previa: n + ' oportunidades abertas e avaliadas', blocos: blocos,
    marca: { canal: 'semanal', avisos: ids, atualizacoes: [] }
