    atual.forEach(function (e) {
      var i = e.i, a = e.a;
      var mud = (txt(e.op.motivo).match(/atualizada por retifica[çc][ãa]o em [^|]*/gi) || []).pop() || '';
      blocos.push(H(i.titulo));
      blocos.push(CAMPOS([
        { rotulo: i.prog ? 'Data limite atual' : 'Prazo atual', valor: i.prazo ? br(i.prazo) + ' (' + faltam(diasAte(i.prazo, hoje)) + ')' : 'não informado' },
        { rotulo: 'Valor atual', valor: i.valor || 'não informado' },
        { rotulo: 'O que mudou', valor: mud ? mud.replace(/^atualizada por /i, '').trim() : 'prazo ou valor' },
        { rotulo: 'Resposta atual', valor: SIT[a.situacao] || a.situacao }
      ]));
      blocos.push(blocoLink(e.i));
      if (DECIDIVEL.indexOf(a.situacao) >= 0) blocos.push(botoesDecisao(a.token));
    });
  }
  var n = novas.length, partes = [];
  if (n) partes.push(n + (n === 1 ? ' nova oportunidade' : ' novas oportunidades'));
  if (atual.length) partes.push(atual.length + (atual.length === 1 ? ' atualização' : ' atualizações'));
  var prox = mostradas.length ? mostradas[0].i.prazo : '';
  return [novoEmail(o.cfg, o.ctx, {
    assunto: 'Oportunidades: ' + partes.join(' e ') + (prox ? ' (próximo prazo ' + br(prox) + ')' : ''),
    etiqueta: 'Captação de oportunidades', titulo: 'Aviso diário de oportunidades', previa: partes.join(' e '), blocos: blocos,
    marca: {
      canal: 'diario',
      avisos: mostradas.filter(function (e) { return e.marcar; }).map(function (e) { return e.a.id; }),
      atualizacoes: atual.filter(function (e) { return e.marcar; }).map(function (e) { return e.a.id; })
    }
  })];
}

// ---------- resumo semanal ----------
function resumoSemanal(o) {
  var hoje = o.hoje, limite30 = somaDias(hoje, 30), inicioSemana = somaDias(hoje, -7);
  var todas = elegiveis(o);
  var abertas = todas.filter(function (e) { return aberta(e.i, hoje) && ['nova', 'avisada', 'talvez', 'concorrer'].indexOf(e.a.situacao) >= 0; }).sort(function (x, y) { return porPrazo(x.i, y.i); });
  var prox = abertas.filter(function (e) { return e.i.prazo && e.i.prazo <= limite30; });
  var semDecisao = abertas.filter(function (e) { return ['nova', 'avisada', 'talvez'].indexOf(e.a.situacao) >= 0; });
  var pouco = semDecisao.filter(function (e) { return e.a.recomendacao === 'nao_seguir'; });
  var progs = semDecisao.filter(function (e) { return e.a.recomendacao !== 'nao_seguir' && e.i.prog; });
  var editais = semDecisao.filter(function (e) { return e.a.recomendacao !== 'nao_seguir' && !e.i.prog; });
  if (!abertas.length) return [];
  var mostrados = {};
  function ate(lista) { var r = lista.slice(0, LIMITE_SECAO); r.forEach(function (e) { mostrados[e.a.id] = e; }); return r; }
  function resto(lista) { return lista.length > LIMITE_SECAO ? [AV('Mais ' + (lista.length - LIMITE_SECAO) + ' nesta seção não cabem neste e-mail; entram nas próximas segundas, conforme os prazos passam.')] : []; }
  var blocos = [PT('Resumo do que está aberto e avaliado, por prazo. Responda pelos botões de cada oportunidade ainda sem decisão. ' + NOTA_BOTOES)];
  if (prox.length) {
    blocos.push(H('Prazos dos próximos 30 dias (' + prox.length + ')'));
    var pl = ate(prox);
    blocos.push(UL(pl.map(function (e) { return br(e.i.prazo) + ' — ' + e.i.titulo + (e.i.prog ? ' (programa aberto)' : '') + ' — ' + (SIT[e.a.situacao] || e.a.situacao); })));
    blocos = blocos.concat(resto(prox));
  }
  if (editais.length) {
    blocos.push(H('Abertas, ainda sem decisão (' + editais.length + ')'));
    ate(editais).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(editais));
  }
  if (progs.length) {
    blocos.push(H('Programas abertos a propostas (sem seleção) (' + progs.length + ')'));
    blocos.push(PT(EXPLICA_PROGRAMA));
    ate(progs).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(progs));
  }
  if (pouco.length) {
    blocos.push(H('Avaliadas como pouco aderentes (' + pouco.length + ')'));
    blocos.push(PT('Ficaram com recomendação de não seguir; estão aqui para conferência.'));
    ate(pouco).forEach(function (e) { blocos = blocos.concat(blocosItem(e, hoje, false, true)); });
    blocos = blocos.concat(resto(pouco));
  }
  // decisões e resultados dos últimos 7 dias
  var feitos = todas.filter(function (e) {
    var d = dia(e.a.resultado_em) || dia(e.a.decidido_em);
    return d && d >= inicioSemana && ['concorrer', 'talvez', 'nao_serve', 'enviada', 'ganhou', 'perdeu', 'desistiu'].indexOf(e.a.situacao) >= 0;
  });
  if (feitos.length) {
    blocos.push(H('Decisões e resultados da semana (' + feitos.length + ')'));
    blocos.push(UL(feitos.map(function (e) {
      var s = SIT[e.a.situacao] + (e.a.situacao === 'nao_serve' && txt(e.a.motivo_nao_serve) ? ' (motivo: ' + e.a.motivo_nao_serve + ')' : '') + (e.a.situacao === 'desistiu' && txt(e.a.motivo_desistencia) ? ' (motivo: ' + e.a.motivo_desistencia + ')' : '');
      return e.i.titulo + (e.i.prog ? ' (programa aberto)' : '') + ' — ' + s;
    })));
  }
  // quadro por fonte, desde o início
  var q = {};
  todas.forEach(function (e) {
    var f = e.i.fonte || 'Sem fonte', r = q[f] || (q[f] = { avisadas: 0, concorrer: 0, enviadas: 0, ganhas: 0 }), a = e.a;
    if (a.avisado_em || a.situacao !== 'nova') r.avisadas++;
    if (['concorrer', 'enviada', 'ganhou', 'perdeu', 'desistiu'].indexOf(a.situacao) >= 0) r.concorrer++;
    if (['enviada', 'ganhou', 'perdeu'].indexOf(a.situacao) >= 0 || (a.situacao === 'desistiu' && a.enviada_em)) r.enviadas++;
    if (a.situacao === 'ganhou') r.ganhas++;
  });
  var fontes = Object.keys(q).filter(function (f) { return q[f].avisadas || q[f].concorrer; }).sort(function (x, y) { return (q[y].avisadas - q[x].avisadas) || x.localeCompare(y); });
  if (fontes.length) {
    blocos.push(H('Quadro por fonte (desde o início)'));
    blocos.push(CAMPOS(fontes.map(function (f) { return { rotulo: f, valor: 'avisadas ' + q[f].avisadas + ' · concorrer ' + q[f].concorrer + ' · enviadas ' + q[f].enviadas + ' · ganhas ' + q[f].ganhas }; })));
  }
  // as avaliações "nova" que entraram no e-mail viram avisada (canal semanal); linha de base inclusive
  var ids = Object.keys(mostrados).map(function (k) { return mostrados[k]; }).filter(function (e) { return e.a.situacao === 'nova' && e.marcar; }).map(function (e) { return e.a.id; });
  var n = abertas.length;
  return [novoEmail(o.cfg, o.ctx, {
    assunto: 'Resumo semanal de oportunidades: ' + n + (n === 1 ? ' aberta' : ' abertas') + (prox.length ? ', ' + prox.length + ' com prazo em 30 dias' : ''),
    etiqueta: 'Captação de oportunidades', titulo: 'Resumo semanal de oportunidades', previa: n + ' oportunidades abertas e avaliadas', blocos: blocos,
    marca: { canal: 'semanal', avisos: ids, atualizacoes: [] }
  })];
}

// modo: 'diario', 'semanal' ou 'manual' (os dois, para teste). Sem novidade, sem e-mail.
function montarAvisos(o) {
  var modo = o.modo;
  var saida = [];
  if (modo === 'diario' || modo === 'manual') saida = saida.concat(avisoDiario(o));
  if (modo === 'semanal' || modo === 'manual') saida = saida.concat(resumoSemanal(o));
  return saida;
}

// Linhas a gravar depois do envio: só o que o subfluxo confirmou (resposta com id).
function linhasAMarcar(email, resposta, agoraIso) {
  if (!enviado(resposta) || !email || !email._marca) return [];
  var m = email._marca, out = [];
  (m.avisos || []).forEach(function (id) { out.push({ id: id, tipo: 'aviso', canal_aviso: m.canal, avisado_em: agoraIso }); });
  (m.atualizacoes || []).forEach(function (id) { out.push({ id: id, tipo: 'atualizacao', canal_aviso: '', avisado_em: agoraIso }); });
  return out;
}

const resposta = $input.item.json || {};
const email = $('Montar e-mails').item.json || {};
return { json: { assunto: email.assunto, ok: enviado(resposta), marcas: linhasAMarcar(email, resposta, $now.toISO()) } };

// Só marca o que o subfluxo confirmou (resposta com id). E-mail que falhou fica para a próxima rodada.
const out = [];
for (const it of $input.all()) for (const m of ((it.json || {}).marcas || [])) out.push({ json: m });
return out;
